#!/usr/bin/env python"""periodicity_QC_visualiser.py============================QC panels for birdsong detectors.Colours-------yellow : periodicity_detected_song_timespink   : amplitude_detected_song_timesblue   : wiener_detected_song_timesred ‑‑ : dashed file boundary"""from __future__ import annotationsimport argparseimport jsonfrom pathlib import Pathfrom typing import List, Tupleimport numpy as npimport matplotlib.pyplot as pltimport matplotlib.patches as mpatchesimport soundfile as sffrom scipy.signal import spectrogramROW_DUR = 10.0          # seconds shown per row# ───────────────────── helper: short spectrogram ─────────────────────def _draw_segment(ax, audio, sr, offset, dur, *, vmin=-90, vmax=-20):    if dur <= 0:        return    f, t, S = spectrogram(        audio[: int(round(dur * sr))],        fs=sr, nperseg=1024, noverlap=512,        scaling="spectrum", mode="magnitude",    )    S_db = 20 * np.log10(S + 1e-12)    ax.pcolormesh(offset + t, f, S_db,                  shading="auto", cmap="gray_r",                  vmin=vmin, vmax=vmax)def _highlight_spans(ax, spans, pane_offset, seg_dur, *, colour, alpha=0.1):    """Highlight spans intersecting this segment."""    for s, e in spans:        if e <= 0 or s >= seg_dur:            continue        ax.axvspan(pane_offset + max(s, 0),                   pane_offset + min(e, seg_dur),                   color=colour, alpha=alpha, zorder=5)# ───────────────────────── legend figure ─────────────────────────def save_legend_png(output_dir: Path) -> None:    fig, ax = plt.subplots(figsize=(4, 2))    ax.axis("off")    handles = [        mpatches.Patch(color="yellow", label="Periodicity detected song"),        mpatches.Patch(color="pink",   label="Amplitude detected song"),        mpatches.Patch(color="blue",   label="Wiener‑entropy detected song"),        plt.Line2D([0], [0], color="red", lw=2, ls="--",                   label="File boundary"),    ]    ax.legend(handles=handles, frameon=False, loc="center")    fig.savefig(output_dir / "periodicity_QC_key.png",                dpi=300, bbox_inches="tight")    plt.close(fig)    print(f"[INFO] Saved {output_dir/'periodicity_QC_key.png'}")# ─────────────────────────── build QC figures ───────────────────────────def build_QC_panels(json_path,                    output_dir,                    *,                    sr: int = 44100,                    rows_per_fig: int = 6) -> None:    """    Create PNG QC panels where *every second of every recording is shown*.    Each row is ROW_DUR seconds wide; long clips automatically wrap to    the next row (and next figure if needed).    """    json_path, output_dir = Path(json_path), Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    with json_path.open() as f:        recs_all = json.load(f)    # keep only items that have periodicity detections    recs = [r for r in recs_all            if r.get("metrics", {})                 .get("periodicity_detected_song_times")]    if not recs:        print("[WARN] No recordings with periodicity detections found.")        return    legend_written = False    rec_idx, rec_progress, fig_no = 0, 0.0, 1       # progress in seconds    while rec_idx < len(recs):        fig, axes = plt.subplots(            rows_per_fig, 1,            figsize=(10, 2 * rows_per_fig),            sharex=True, constrained_layout=True,        )        axes = np.atleast_1d(axes)        for ax in axes:            if rec_idx >= len(recs):                ax.axis("off")                continue            offset = 0.0          # seconds along this row            titles = []            while offset < ROW_DUR and rec_idx < len(recs):                rec      = recs[rec_idx]                metrics  = rec["metrics"]                wav_path = Path(rec["file_path"])                # load audio once per recording                if rec_progress == 0.0:                    audio_full, sr_file = sf.read(wav_path)                    if audio_full.ndim > 1:                        audio_full = audio_full.mean(axis=1)                    if sr_file != sr:                        print(f"[WARN] {wav_path.name}: "                              f"sr {sr_file} != {sr}; using {sr_file}")                        sr = sr_file                remaining = rec["duration_seconds"] - rec_progress                seg_dur   = min(remaining, ROW_DUR - offset)                # slice the part we need                start_samp = int(round(rec_progress * sr))                seg_audio  = audio_full[start_samp:                                        start_samp + int(round(seg_dur * sr))]                _draw_segment(ax, seg_audio, sr, offset, seg_dur)                # shift all detector spans by –rec_progress to get them                # into the coordinate frame of this segment                shift = rec_progress                _highlight_spans(ax,                                 [(s - shift, e - shift)                                  for s, e                                  in metrics["periodicity_detected_song_times"]],                                 offset, seg_dur, colour="yellow")                _highlight_spans(ax,                                 [(s - shift, e - shift)                                  for s, e                                  in metrics["amplitude_detected_song_times"]],                                 offset, seg_dur, colour="pink")                _highlight_spans(ax,                                 [(s - shift, e - shift)                                  for s, e                                  in metrics["wiener_detected_song_times"]],                                 offset, seg_dur, colour="blue")                rec_progress += seg_dur                offset       += seg_dur                # draw boundary only if we just finished the recording                finished_clip = abs(rec_progress - rec["duration_seconds"]) < 1e-6                if finished_clip:                    ax.axvline(offset, color="red", ls="--", lw=1.0, zorder=6)                    titles.append(wav_path.name)                    rec_idx      += 1     # move to next recording                    rec_progress  = 0.0   # reset progress for next clip                # otherwise we'll loop again and continue same recording            # cosmetics for this row            ax.set_xlim(0, ROW_DUR)            ax.set_ylim(0, 10_000)            ax.set_yticks([0, 2500, 5000, 7500, 10_000])            ax.set_ylabel("Freq [Hz]")            ax.tick_params(labelsize=8)            if titles:                ax.set_title(" + ".join(titles), fontsize=9, pad=4)        axes[-1].set_xlabel("Time [s]")        fig.suptitle(f"Periodicity QC panel {fig_no}", fontsize=12)        out_png = output_dir / f"periodicity_QC_panel_{fig_no:03d}.png"        fig.savefig(out_png, dpi=300)        plt.close(fig)        print(f"[INFO] Saved {out_png}")        if not legend_written:            save_legend_png(output_dir)            legend_written = True        fig_no += 1# ────────────────────────── CLI entry ──────────────────────────if __name__ == "__main__":    p = argparse.ArgumentParser(        description="Visual QC for periodicity song detector."    )    p.add_argument("--json_path",  required=True, type=str)    p.add_argument("--output_dir", required=True, type=str)    p.add_argument("--sr",      default=44100, type=int)    p.add_argument("--rows",    default=6,     type=int,                   dest="rows_per_fig",                   help="Rows (timelines) per figure.")    args = p.parse_args()    build_QC_panels(args.json_path,                    args.output_dir,                    sr=args.sr,                    rows_per_fig=args.rows_per_fig)